 const voice=$('.voice-alternative');if(voice){const label=loading?'Preparing':sensor.speech==='listening'?'Listening':sensor.speech==='starting'?'Starting':sensor.speech==='unsupported'?'Voice unavailable':sensor.speech==='error'?'Retry voice':'Speak';voice.disabled=loading||sensor.speech==='starting';const text=voice.querySelector('span');if(text)text.textContent=label;voice.setAttribute('aria-label',label);}
