function dailySnapshot(){const tab=s.dailyTab||'health',previous=previousDailyFeedback(s.dailyFeedback,today,tab,s.dailyOutcomes,s.dailySnapshots,s.baziRevision||0);if(tab==='health')return dailyHealth(today,previous,previousSnapshot(tab)?.text,s.sampleProfileId).headline;if(tab==='meaning')return s.baziPillars?dailyPreview(today,s.baziPillars,previous,previousSnapshot(tab)?.text).theme:'Four pillars not provided';return dailyConnection(today,previous,previousSnapshot(tab)?.text,s.source==='sample'?s.sampleProfileId:null).headline;}
