document.addEventListener('change',async e=>{if(!['local-files','local-picked-files','global-local-files','global-picked-files','global-calendar-file'].includes(e.target?.id))return;const selected=e.target.files;if(!selected?.length)return;if(e.target.id==='global-calendar-file'){try{const learned=await readCalendarExport(selected[0]);close();act('app-read',learned)}catch(err){toast(err.message)}e.target.value='';return;}await analyzeSelected(selected);e.target.value='';});

finishOuraAuthorization().then(data=>{if(data)act('app-read',data)}).catch(err=>toast(err.message));

let scanController;
async function connectComputer(){
 if($('#drawer').open)close();
 if(!window.showDirectoryPicker){$('#global-local-files')?.click();return;}
 scanController?.abort();const controller=scanController=new AbortController();try{const handle=await showDirectoryPicker({mode:'read'});if(controller.signal.aborted)return;showScan({phase:'Mapping your folder',discovered:0});const files=await filesFromDirectory(handle,p=>showScan({phase:'Mapping your folder',...p}),{signal:controller.signal});await analyzeSelected(files,controller)}catch(err){if(err?.name!=='AbortError')toast(err?.message||'Folder access was not granted.');render()}
}
function showScan(p){$('#shell').dataset.stage='scanning';const count=p.read??p.discovered??0;$('#app').innerHTML=`<section class="device-scan local-scan"><span class="device-index">READING LOCALLY</span><div class="scan-progress" role="progressbar" aria-label="Preparing your mirror"><i></i></div><h1>${esc(p.phase||'Reading locally')}</h1><div class="scan-list"><div><b>Found</b><span>${p.discovered||0}</span></div><div><b>Read</b><span>${count}${p.total?' / '+p.total:''}</span></div></div><p>On this device</p></section>`}
async function analyzeSelected(files,controller){if(!controller){scanController?.abort();controller=scanController=new AbortController()}showScan({phase:'Finding what matters',discovered:files.length,read:0});try{const learned=await learnFromFiles(files,p=>showScan({phase:'Finding what matters',...p}),{signal:controller.signal});if(controller.signal.aborted)return;if(!learned.count){render();toast('No readable documents were found in that folder. Try another folder.');return}if($('#drawer').open)close();act('local-read',learned)}catch(err){if(err.name==='AbortError')return;render();toast(err.message||'This folder could not be read.')}}

const BRIDGE='http://127.0.0.1:8768';
async function bridgeRequest(path,{post=false}={}){const response=await fetch(BRIDGE+path,{method:post?'POST':'GET',headers:{...(post?{'X-Loka-Token':bridgeToken}:{}),'Content-Type':'application/json'},cache:'no-store'});if(!response.ok)throw Error('Local reader is not available.');return response.json()}
async function startBridgeScan(){
 const msg=$('#bridge-message');if(msg)msg.textContent='Connecting to the local reader…';
 try{const health=await bridgeRequest('/health');if(!health.ready)throw Error('Local reader is not ready.');bridgeToken=health.token;await bridgeRequest('/scan',{post:true});close();showScan({phase:'Finding your documents',discovered:0,read:0});pollBridge()}
 catch(err){if(msg)msg.textContent='Local reader is unavailable on this Mac. Reopen the desktop demo to retry.';toast(err.message)}
}
async function pollBridge(){
 try{const status=await bridgeRequest('/status');if(status.status==='done'){bridgeTimer=null;if(!status.result?.count){render();toast('No readable personal documents were found.');return}act('local-read',status.result);return}
 if(status.status==='error'){bridgeTimer=null;render();toast(status.error||'Local scan stopped.');return}
 showScan({phase:status.status==='mapping'?'Finding your documents':'Reading what matters',discovered:status.found,read:status.read,total:status.total,path:status.path});bridgeTimer=setTimeout(pollBridge,350)}
 catch(err){bridgeTimer=null;render();toast('Connection to the local reader was lost.')}
}
function clearBridge(){clearTimeout(bridgeTimer);bridgeTimer=null;if(bridgeToken)bridgeRequest('/clear',{post:true}).catch(()=>{});bridgeToken=''}
